import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useTheme } from "next-themes";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Layers, LogOut, Settings, ShieldCheck,
  AlertTriangle, Wallet, Sun, Moon, Monitor,
  User, CalendarCheck, CreditCard,
} from "lucide-react";
import { Link } from "react-router-dom";
import AuthDialog from "@/components/AuthDialog";

function getInitials(email?: string | null): string {
  if (!email) return "?";
  const name = email.split("@")[0];
  const parts = name.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name[0]?.toUpperCase() || "?";
}

function getUserName(email?: string | null): string {
  if (!email) return "User";
  const name = email.split("@")[0];
  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

const AppHeader = ({ onLogoClick }: { onLogoClick?: () => void }) => {
  const { user, profile, isAdmin, signOut } = useAuth();
  const { theme, setTheme: rawSetTheme } = useTheme();
  const setTheme = (t: string) => {
    document.documentElement.classList.add("disable-transitions");
    rawSetTheme(t);
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        document.documentElement.classList.remove("disable-transitions");
      });
    });
  };
  const [authOpen, setAuthOpen] = useState(false);
  const [authTab, setAuthTab] = useState<"signin" | "signup">("signin");
  const navigate = useNavigate();

  const openAuth = (tab: "signin" | "signup") => { setAuthTab(tab); setAuthOpen(true); };

  const subCredits = profile?.subscription_credits ?? 0;
  const topCredits = profile?.topup_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const splitTotal = subCredits + topCredits + bonusCredits;
  const legacyCredits = profile?.credits ?? 0;
  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
  const isLowCredits = totalCredits < 3;

  const initials = getInitials(user?.email);

  return (
    <>
      <header className="border-b border-border bg-card">
        <div className="mx-auto max-w-[1200px] px-4 sm:px-6 flex items-center justify-between h-14">
          <Link to="/" className="flex items-center gap-2" onClick={(e) => { if (onLogoClick) { e.preventDefault(); onLogoClick(); } }}>
            <Layers className="h-5 w-5 text-primary" />
            <span className="font-semibold text-foreground tracking-tight">Rankora</span>
          </Link>

          <div className="flex items-center gap-2">
            {user ? (
              <>
                {/* Credits */}
                <button
                  onClick={() => navigate("/billing")}
                  className={`group inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 outline-none focus-visible:ring-2 focus-visible:ring-offset-2 border ${
                    isLowCredits
                      ? "border-destructive/40 text-destructive hover:border-destructive hover:bg-destructive/5 focus-visible:ring-destructive"
                      : "border-border text-foreground hover:border-foreground/40 hover:bg-muted focus-visible:ring-ring"
                  }`}
                >
                  {isLowCredits ? <AlertTriangle className="h-4 w-4" /> : <Wallet className="h-4 w-4 text-muted-foreground" />}
                  <span className="text-sm font-medium tabular-nums">{totalCredits}</span>
                  <span className="text-[11px] font-medium text-muted-foreground">Credits</span>
                </button>

                {/* Profile dropdown */}
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button className="h-9 w-9 rounded-lg bg-primary text-primary-foreground text-sm font-bold flex items-center justify-center hover:bg-primary/90 transition-all cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1" aria-label="Account menu">
                      {initials}
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-56 mt-1.5 p-0">
                    {/* User info header */}
                    <div className="px-4 py-3">
                      <p className="text-sm font-semibold text-foreground">{getUserName(user.email)}</p>
                      <p className="text-xs text-muted-foreground truncate">{user.email}</p>
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    {/* Theme switcher */}
                    <div className="px-4 py-2.5 flex items-center justify-between">
                      <span className="text-sm text-foreground">Theme</span>
                      <div className="flex items-center rounded-lg border border-border bg-muted/50 p-0.5">
                        <button
                          onClick={(e) => { e.preventDefault(); setTheme("light"); }}
                          className={`p-1.5 rounded-md transition-colors ${theme === "light" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                          aria-label="Light theme"
                        >
                          <Sun className="h-3.5 w-3.5" />
                        </button>
                        <button
                          onClick={(e) => { e.preventDefault(); setTheme("dark"); }}
                          className={`p-1.5 rounded-md transition-colors ${theme === "dark" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                          aria-label="Dark theme"
                        >
                          <Moon className="h-3.5 w-3.5" />
                        </button>
                        <button
                          onClick={(e) => { e.preventDefault(); setTheme("system"); }}
                          className={`p-1.5 rounded-md transition-colors ${theme === "system" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                          aria-label="System theme"
                        >
                          <Monitor className="h-3.5 w-3.5" />
                        </button>
                      </div>
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    {/* Menu items */}
                    <div className="py-1">
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/profile")}>
                        <User className="h-4 w-4 mr-2.5" />
                        Profile
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/billing")}>
                        <CreditCard className="h-4 w-4 mr-2.5" />
                        Billing & Plan
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/settings")}>
                        <Settings className="h-4 w-4 mr-2.5" />
                        Settings
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/book-demo")}>
                        <CalendarCheck className="h-4 w-4 mr-2.5" />
                        Book Demo
                      </DropdownMenuItem>
                      {isAdmin && (
                        <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/admin")}>
                          <ShieldCheck className="h-4 w-4 mr-2.5" />
                          Admin
                        </DropdownMenuItem>
                      )}
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    <div className="py-1">
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={signOut}>
                        <LogOut className="h-4 w-4 mr-2.5" />
                        Log out
                      </DropdownMenuItem>
                    </div>
                  </DropdownMenuContent>
                </DropdownMenu>
              </>
            ) : (
              <>
                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>Sign in</Button>
                <Button size="sm" onClick={() => openAuth("signup")}>Sign up free</Button>
              </>
            )}
          </div>
        </div>
      </header>
      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
    </>
  );
};

export default AppHeader;

