76	    if (!user) return;
77	    setLoadingPastJobs(true);
78	    try {
79	      const { data: jobs } = await supabase
80	        .from("jobs")
81	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
