53	function getJobIconProps(title: string | null, index: number) {
54	  const lower = (title ?? "").toLowerCase();
55	  let iconIndex = index % JOB_ICONS.length;
56	
57	  if (lower.includes("engineer") || lower.includes("developer") || lower.includes("dev") || lower.includes("code")) {
