        };
      });
      // Deduplicate by resume_id — keep highest scoring result per resume
      const deduped = new Map<string, Result>();
      for (const r of allMerged) {
        const existing = deduped.get(r.resume_id);
        if (!existing || r.overall_score > existing.overall_score) {
          deduped.set(r.resume_id, r);
        }
      }
      const merged = Array.from(deduped.values());
      merged.sort((a, b) => b.overall_score - a.overall_score);
      setResults(merged);
    } catch (err) {
      toast.error("Failed to load job data");
    }
  };

  const handleNewJob = () => {
    setSelectedJobId(null);
    setShowDashboard(false);
    setResults([]);
    setExistingResumes([]);
  };

  const handleGoToDashboard = () => {
    setSelectedJobId(null);
    setShowDashboard(true);
    setResults([]);
    setExistingResumes([]);
  };

  const handleJobCreated = (job: PastJob) => {
    setPastJobs((prev) => [job, ...prev]);
    setSelectedJobId(job.id);
    loadJobData(job.id);
  };

  const handleRenameJob = (jobId: string, newTitle: string) => {
    setPastJobs((prev) =>
      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
    );
  };

  const handleDeleteJob = async (jobId: string) => {
    try {
      await supabase.from("resumes").delete().eq("job_id", jobId);
      await supabase.from("jobs").delete().eq("id", jobId);
      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
      if (selectedJobId === jobId) handleNewJob();
      toast.success("Job deleted");
    } catch {
      toast.error("Failed to delete job");
    }
  };

  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
    setPastJobs((prev) =>
      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
    );
  };

  const requireAuth = useCallback(() => {
    if (!user) { setAuthOpen(true); return true; }
    return false;
  }, [user]);

  return (
    <SidebarProvider className="h-svh overflow-hidden">
      <JobSidebar
        pastJobs={pastJobs}
        selectedJobId={selectedJobId}
        showDashboard={showDashboard}
        loadingPastJobs={loadingPastJobs}
        onSelectJob={loadJobData}
        onNewJob={handleNewJob}
        onDashboard={handleGoToDashboard}
        onRenameJob={handleRenameJob}
        onDeleteJob={handleDeleteJob}
        onAuthRequired={() => setAuthOpen(true)}
        isAuthenticated={!!user}
      />

      <SidebarInset className="h-svh overflow-y-auto">
        <AppHeader onLogoClick={user ? handleGoToDashboard : undefined} />
        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
          <SidebarTrigger />
          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
        </div>

        {/* Dashboard view */}
        {showDashboard && !selectedJobId && user ? (
          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
            {/* Greeting */}
            <div>
              <h1 className="text-xl font-semibold text-foreground">Welcome back</h1>
              <p className="text-sm text-muted-foreground mt-0.5">{user.email}</p>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {[
                { label: "Jobs", value: pastJobs.length, icon: Briefcase },
                { label: "Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText },
                { label: "Credits", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins },
                { label: "Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2 },
              ].map((s) => (
                <Card key={s.label}>
                  <CardContent className="px-4 py-3 flex items-center gap-3">
                    <div className="h-8 w-8 rounded-lg bg-muted flex items-center justify-center shrink-0">
                      <s.icon className="h-4 w-4 text-muted-foreground" />
                    </div>
                    <div>
                      <p className="text-xl font-semibold tabular-nums text-foreground">{s.value}</p>
                      <p className="text-xs text-muted-foreground">{s.label}</p>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>

            {/* Quick start */}
            <Button className="gap-2" onClick={handleNewJob}>
              <Plus className="h-4 w-4" /> Create New Job
            </Button>

            {/* Jobs Overview */}
            <JobsOverviewCard
              jobs={pastJobs}
              loading={loadingPastJobs}
              onSelectJob={loadJobData}
            />

            {/* Getting started guide */}
            <Card>
              <CardContent className="px-5 py-4 space-y-3">
                <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
                <div className="space-y-2.5">
                  {[
                    { step: "1", text: "Click \"Create New Job\" and paste a job description" },
                    { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
                    { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
                  ].map((item) => (
                    <div key={item.step} className="flex items-start gap-3 text-sm">
                      <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
                      <span className="text-muted-foreground">{item.text}</span>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          </div>
        ) : (
          <JobDetailView
            selectedJobId={selectedJobId}
            selectedJob={selectedJob}
            results={results}
            setResults={setResults}
            existingResumes={existingResumes}
            setExistingResumes={setExistingResumes}
            onJobCreated={handleJobCreated}
            onAuthRequired={() => setAuthOpen(true)}
            isAuthenticated={!!user}
            pastJobs={pastJobs}
            onJobUpdated={handleJobUpdated}
          />
        )}
      </SidebarInset>

      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
    </SidebarProvider>
  );
};

export default Index;

