import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Database, ChevronDown, AlertTriangle, Plus, Zap, Gift, CreditCard } from "lucide-react";
import { useState } from "react";

const WalletDropdown = () => {
  const { profile } = useAuth();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);

  const subCredits = profile?.subscription_credits ?? 0;
  const topCredits = profile?.topup_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const splitTotal = subCredits + topCredits + bonusCredits;
  const legacyCredits = profile?.credits ?? 0;
  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
  const isLowCredits = totalCredits < 3;
  const hasSplitCredits = splitTotal > 0;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          className={`group inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 outline-none focus-visible:ring-2 focus-visible:ring-offset-2 border transition-all ${
            isLowCredits
              ? "border-destructive/40 text-destructive hover:border-destructive hover:bg-destructive/5 focus-visible:ring-destructive"
              : "border-border bg-muted/50 text-foreground hover:border-foreground/30 hover:bg-muted focus-visible:ring-ring"
          }`}
        >
          {isLowCredits ? (
            <AlertTriangle className="h-4 w-4 shrink-0" />
          ) : (
            <Database className="h-4 w-4 shrink-0 text-primary" />
          )}
          <span className="text-sm font-semibold tabular-nums">{totalCredits.toLocaleString()}</span>
          <span className="text-[11px] font-medium text-muted-foreground">Credits</span>
          <ChevronDown className={`h-3 w-3 text-muted-foreground transition-transform ${open ? "rotate-180" : ""}`} />
        </button>
      </PopoverTrigger>

      <PopoverContent align="end" className="w-64 p-0">
        {/* Header */}
        <div className="px-4 pt-3.5 pb-3">
          <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Credit Balance</p>
          <p className="text-2xl font-bold tabular-nums text-foreground mt-1">
            {totalCredits.toLocaleString()}
          </p>
        </div>

        {/* Breakdown */}
        {hasSplitCredits && (
          <>
            <Separator />
            <div className="px-4 py-3 space-y-2">
              <CreditRow icon={Zap} label="Subscription" value={subCredits} color="text-blue-500" />
              <CreditRow icon={CreditCard} label="Top-up" value={topCredits} color="text-emerald-500" />
              <CreditRow icon={Gift} label="Bonus" value={bonusCredits} color="text-amber-500" />
            </div>
          </>
        )}

        {/* Low credits warning */}
        {isLowCredits && (
          <>
            <Separator />
            <div className="px-4 py-2.5 bg-destructive/5">
              <p className="text-xs text-destructive font-medium">
                Running low on credits. Top up to keep ranking.
              </p>
            </div>
          </>
        )}

        {/* Actions */}
        <Separator />
        <div className="p-2">
          <Button
            size="sm"
            className="w-full gap-2"
            onClick={() => { setOpen(false); navigate("/billing"); }}
          >
            <Plus className="h-3.5 w-3.5" />
            Buy Credits
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
};

function CreditRow({
  icon: Icon,
  label,
  value,
  color,
}: {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  value: number;
  color: string;
}) {
  return (
    <div className="flex items-center justify-between">
      <div className="flex items-center gap-2">
        <Icon className={`h-3.5 w-3.5 ${color}`} />
        <span className="text-xs text-muted-foreground">{label}</span>
      </div>
      <span className="text-xs font-semibold tabular-nums text-foreground">{value.toLocaleString()}</span>
    </div>
  );
}

export default WalletDropdown;

